from itertools import permutations
from functools import lru_cache

def solve_brute(n):
    """Brute force: try all permutations, return min total uphill paths."""
    cells = [(i,j) for i in range(n) for j in range(n)]
    N = n*n
    best = None
    best_perm = None

    for perm in permutations(range(1, N+1)):
        # perm[k] = value at cells[k]
        val = {cells[k]: perm[k] for k in range(N)}

        # neighbors
        def nbrs(i,j):
            res = []
            for di,dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                ni,nj = i+di, j+dj
                if 0<=ni<n and 0<=nj<n:
                    res.append((ni,nj))
            return res

        # g(v) = number of increasing paths starting at v
        # process cells in decreasing order of value
        order = sorted(cells, key=lambda c: -val[c])
        g = {}
        for c in order:
            g[c] = 1
            for nb in nbrs(*c):
                if val[nb] > val[c]:
                    g[c] += g[nb]

        # valleys: cells where all neighbors have larger value
        total = 0
        for c in cells:
            is_valley = all(val[nb] > val[c] for nb in nbrs(*c))
            if is_valley:
                total += g[c]

        if best is None or total < best:
            best = total
            best_perm = perm

    return best, best_perm

for n in range(1, 4):
    b, bp = solve_brute(n)
    print(f"n={n}: min total uphill paths = {b}, perm = {bp}")
