    """Count total uphill paths for a given grid."""
    cells = [(i,j) for i in range(n) for j in range(n)]
    val = {(i,j): grid[i][j] for i in range(n) for j in range(n)}

    def nbrs(i,j):
        res = []
        for di,dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni,nj = i+di, j+dj
            if 0<=ni<n and 0<=nj<n:
                res.append((ni,nj))
        return res

    order = sorted(cells, key=lambda c: -val[c])
    g = {}
    for c in order:
        g[c] = 1
        for nb in nbrs(*c):
            if val[nb] > val[c]:
                g[c] += g[nb]

    total = 0
    for c in cells:
        if all(val[nb] > val[c] for nb in nbrs(*c)):
            total += g[c]
    return total

# n=4 construction
grid4 = [
    [16, 1, 2, 3],
    [8, 12, 4, 13],
    [7, 6, 5, 10],
    [9, 14, 11, 15]
]
